code_sketch:
class Grantor:                      # owns the implementation
    private A(int); B(float); C(double)
    friend Attorney                 # exactly one friend, not the requestor

class Attorney:                     # the only door to A and B
    private static callA(Grantor& g, int a)   { g.A(a) }
    private static callB(Grantor& g, float b) { g.B(b) }
    friend Requestor                # who may use the door

class Requestor:                    # can call A and B, never C
